<?php
namespace App\Http\Controllers;use App\Http\Resources\OperationalEventResource;use App\Models\OperationalEvent;use App\Services\Admin\DeviceAccessService;use Illuminate\Database\Eloquent\Builder;use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class OperationalEventController extends Controller{public function __construct(private DeviceAccessService $access){}public function index(Request $r){$query=$this->scoped($r);$filters=$this->filters($r);$this->apply($query,$filters);return OperationalEventResource::collection($query->with(['device:id,name,device_template_id','device.template:id,name','organization:id,name','automation:id,name'])->orderByDesc('occurred_at')->orderByDesc('id')->paginate($filters['per_page']??25)->withQueryString());}public function show(Request $r,string $event){return new OperationalEventResource($this->scoped($r)->with(['device:id,name,device_template_id','device.template:id,name','organization:id,name','automation:id,name'])->findOrFail($event));}
 private function scoped(Request $r):Builder{$user=$r->user();abort_unless($user->organization&&$user->hasOrganizationPermission('device.view'),403);$deviceIds=$this->access->accessibleDevices($user)->pluck('id');return OperationalEvent::query()->where('organization_id',$user->organization_id)->where(fn(Builder $q)=>$q->where(fn(Builder $org)=>$org->whereNull('device_id')->where('device_bound',false))->orWhereIn('device_id',$deviceIds));}
 private function filters(Request $r):array{return $r->validate(['search'=>['nullable','string','max:255'],'severity'=>['nullable',Rule::in(OperationalEvent::SEVERITIES)],'source'=>['nullable',Rule::in(OperationalEvent::SOURCES)],'event_type'=>['nullable',Rule::in(OperationalEvent::TYPES)],'device_id'=>['nullable','integer'],'from'=>['nullable','date'],'to'=>['nullable','date','after_or_equal:from'],'per_page'=>['nullable','integer',Rule::in([25,50,100])],'page'=>['nullable','integer','min:1']]);}
 private function apply(Builder $q,array $f):void{$q->when($f['severity']??null,fn($x,$v)=>$x->where('severity',$v))->when($f['source']??null,fn($x,$v)=>$x->where('source',$v))->when($f['event_type']??null,fn($x,$v)=>$x->where('event_type',$v))->when($f['device_id']??null,fn($x,$v)=>$x->where('device_id',$v))->when($f['from']??null,fn($x,$v)=>$x->where('occurred_at','>=',$v))->when($f['to']??null,fn($x,$v)=>$x->where('occurred_at','<=',$v))->when($f['search']??null,function($x,$v){$x->where(fn($n)=>$n->where('title','like',"%{$v}%")->orWhere('message','like',"%{$v}%")->orWhere('event_type','like',"%{$v}%")->orWhereHas('device',fn($d)=>$d->where('name','like',"%{$v}%")));});}}
